import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import gsap from 'gsap';
import { pinApi, BASE_URL } from '../utils/api';

// Varied heights: portrait (tall) and landscape (shorter) for masonry / stock-site look
const ASPECT_VARIANTS = ['120%', '155%', '135%', '175%', '145%', '165%', '130%', '160%', '140%', '180%'];
const getAspect = (index) => ASPECT_VARIANTS[index % ASPECT_VARIANTS.length];

const LandingPage = () => {
  const [heroImages, setHeroImages] = useState([]);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const heroImagesRef = useRef({});
  const heroTextRef = useRef(null);
  const dotsRef = useRef(null);

  // Fetch images from admin uploads
  useEffect(() => {
    const fetchHeroImages = async () => {
      try {
        console.log('Fetching pins from API...');
        const pins = await pinApi.getPins();
        console.log('API response:', pins);
        
        // Filter for hero-worthy images (no limit – show all admin uploads)
        const heroPins = pins.filter(pin => pin.image && (pin.title?.length > 0 || pin.description?.length > 0));
        
        console.log('Filtered heroPins:', heroPins);
        setHeroImages(heroPins);
      } catch (error) {
        console.error('Error fetching hero images:', error);
      }
    };

    fetchHeroImages();
  }, []);

  // Auto-rotate images every 4 seconds
  useEffect(() => {
    if (heroImages.length === 0) return;

    const interval = setInterval(() => {
      setCurrentImageIndex(prev => (prev + 1) % heroImages.length);
    }, 4000);

    return () => clearInterval(interval);
  }, [heroImages.length]);

  // Initial page load animations
  useEffect(() => {
    // Hero text animation
    if (heroTextRef.current) {
      // Animate the Creative Stock logo letters with multiple creative effects
      const logoSpans = heroTextRef.current.querySelectorAll('.creative-stock-logo');
      
      // Create staggered animation for each letter
      logoSpans.forEach((span, index) => {
        // Split each word into individual characters for character-by-character animation
        const textContent = span.textContent;
        span.innerHTML = '';
        
        // Create a container for each character
        textContent.split('').forEach((char, charIndex) => {
          const charSpan = document.createElement('span');
          charSpan.textContent = char;
          charSpan.style.display = 'inline-block';
          charSpan.style.margin = '0 2px';
          span.appendChild(charSpan);
          
          // Apply multiple animation effects
          gsap.fromTo(charSpan,
            { 
              opacity: 0, 
              y: index === 0 ? -100 : 100, 
              scale: 0, 
              rotationX: 180,
              rotationY: index === 0 ? -180 : 180
            },
            { 
              opacity: 1, 
              y: 0, 
              scale: 1, 
              rotationX: 0,
              rotationY: 0,
              duration: 1.2, 
              delay: 0.1 * (index * textContent.length + charIndex), 
              ease: "elastic.out(1.2, 0.6)",
              // Additional animation after the initial one
              onComplete: () => {
                // Add a subtle continuous animation
                gsap.to(charSpan, {
                  y: -5,
                  duration: 1,
                  yoyo: true,
                  repeat: -1,
                  ease: "sine.inOut",
                  delay: 0.5
                });
              }
            }
          );
          
          // Add a secondary glow effect
          gsap.fromTo(charSpan,
            { boxShadow: "0 0 0px #ff0000" },
            { 
              boxShadow: index === 0 ? "0 0 5px #666" : "0 0 5px #f00",
              duration: 1.5,
              delay: 0.1 * (index * textContent.length + charIndex) + 0.5,
              repeat: -1,
              yoyo: true,
              ease: "power1.inOut"
            }
          );
        });
      });
      
      // Add overall container animation
      gsap.fromTo(heroTextRef.current,
        { scale: 0.5, rotation: -5 },
        { scale: 1, rotation: 0, duration: 1.5, ease: "elastic.out(1, 0.5)" }
      );
    }

    // Slider dots animation
    if (dotsRef.current) {
      gsap.fromTo(dotsRef.current,
        { opacity: 0, y: 20 },
        { opacity: 1, y: 0, duration: 1, delay: 0.3, ease: "power3.out" }
      );
    }

    // Staggered entrance for gallery images (clean fade-up)
    setTimeout(() => {
      heroImages.forEach((pin, index) => {
        const imgRef = heroImagesRef.current[pin.id];
        if (!imgRef) return;
        gsap.fromTo(imgRef,
          { opacity: 0, y: 28, scale: 0.98 },
          { opacity: 1, y: 0, scale: 1, duration: 0.6, delay: index * 0.04, ease: "power3.out", overwrite: "auto" }
        );
      });
    }, 300);
  }, [heroImages]);

  const imageUrl = (pin) => pin.image?.startsWith('http') ? pin.image : `${BASE_URL}${pin.image || ''}`;

  // U-pattern: left column | logo center | right column, then U-turn row, then masonry
  const n = heroImages.length;
  const leftCount = Math.ceil(n / 3);
  const rightCount = Math.ceil(n / 3);
  const bottomCount = n - leftCount - rightCount;
  const leftImages = heroImages.slice(0, leftCount);
  const rightImages = heroImages.slice(leftCount, leftCount + rightCount);
  const bottomImages = heroImages.slice(leftCount + rightCount);
  const uTurnCount = Math.min(6, Math.max(0, bottomCount));
  const uTurnImages = bottomImages.slice(0, uTurnCount);
  const masonryImages = bottomImages.slice(uTurnCount);

  const ImageCard = ({ pin, className = '', aspect = '160%', index = 0 }) => (
    <Link key={pin.id} to={`/pin/${pin.id}`} className="block">
      <div
        ref={el => {
          if (el) heroImagesRef.current[pin.id] = el;
          else delete heroImagesRef.current[pin.id];
        }}
        className={`relative group overflow-hidden rounded-2xl home-image-card ${className}`}
        style={{ paddingBottom: aspect }}
      >
        <img
          src={imageUrl(pin)}
          alt={pin.title || 'Creative inspiration'}
          className="absolute inset-0 w-full h-full object-cover transition-transform duration-700 ease-out group-hover:scale-105"
          onError={(e) => { e.target.style.display = 'none'; }}
        />
        {/* Pinterest-style light white fade from bottom */}
        <div className="absolute inset-0 bg-gradient-to-t from-white/70 via-white/10 to-transparent pointer-events-none" />
        <div className="absolute inset-0 bg-gradient-to-t from-black/30 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none" />
      </div>
    </Link>
  );

  return (
    <div className="min-h-screen pb-16 bg-white">
      <div className="container mx-auto px-4 max-w-7xl">
        {/* 1. Gap from header, then Creative Stock logo only */}
        <div className="pt-8 pb-4 flex items-center justify-center">
          <div className="flex flex-col items-center justify-center w-full max-w-xl mx-auto">
            <div ref={heroTextRef} className="text-center">
              <h1 className="text-4xl md:text-5xl lg:text-6xl font-bold leading-tight">
                <span className="block text-gray-900 creative-stock-logo" style={{ fontFamily: "'Arial Black', 'Arial Bold', Gadget, sans-serif" }}>Creative</span>
                <span className="block text-red-600 creative-stock-logo" style={{ fontFamily: "'Arial Black', 'Arial Bold', Gadget, sans-serif" }}>Stock</span>
              </h1>
            </div>
            <div ref={dotsRef} className="flex justify-center space-x-2 mt-3">
              {[...Array(3)].map((_, index) => (
                <div
                  key={index}
                  className={`w-2.5 h-2.5 rounded-full transition-all duration-300 ${
                    index === currentImageIndex % 3 ? 'bg-red-600 scale-125' : 'bg-gray-300'
                  }`}
                />
              ))}
            </div>
          </div>
        </div>

        {/* 2. U-shape: first row = images left | gap (under logo) | images right; varying heights */}
        <div className="flex flex-col lg:flex-row items-start justify-center gap-4 lg:gap-6 mt-6 w-full max-w-6xl mx-auto">
          {/* Left of logo – column with varying heights */}
          <div className="w-full lg:w-[35%] grid grid-cols-2 lg:grid-cols-2 gap-3 lg:gap-4 auto-rows-auto">
            {leftImages.map((pin, i) => (
              <div key={pin.id} className="w-full">
                <ImageCard pin={pin} aspect={getAspect(i)} index={i} />
              </div>
            ))}
          </div>
          {/* Center gap – logo is above; no images here so logo is never overlapped */}
          <div className="hidden lg:block lg:w-[30%] flex-shrink-0" aria-hidden="true" />
          {/* Right of logo – column with varying heights */}
          <div className="w-full lg:w-[35%] grid grid-cols-2 lg:grid-cols-2 gap-3 lg:gap-4 auto-rows-auto">
            {rightImages.map((pin, i) => (
              <div key={pin.id} className="w-full">
                <ImageCard pin={pin} aspect={getAspect(leftImages.length + i)} index={leftImages.length + i} />
              </div>
            ))}
          </div>
        </div>

        {/* 3. U-turn row – images below the logo, full width */}
        {uTurnImages.length > 0 && (
          <div className="mt-6 w-full max-w-6xl mx-auto">
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3 lg:gap-4">
              {uTurnImages.map((pin, i) => (
                <ImageCard key={pin.id} pin={pin} aspect={getAspect(leftImages.length + rightImages.length + i)} index={leftImages.length + rightImages.length + i} />
              ))}
            </div>
          </div>
        )}

        {/* 4. Masonry grid – remaining images below U-shape */}
        {masonryImages.length > 0 && (
          <div className="mt-8 w-full max-w-6xl mx-auto home-gallery-masonry">
            {masonryImages.map((pin, i) => (
              <div key={pin.id} className="home-masonry-item">
                <ImageCard pin={pin} aspect={getAspect(leftImages.length + rightImages.length + uTurnImages.length + i)} index={leftImages.length + rightImages.length + uTurnImages.length + i} />
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default LandingPage;
